// who plays which phrase: [start beat, phrase, transpose, stretch (2 = half speed)]
const LEAD = [[0,"REST",0,1],[16,"REST",0,1],[80,"A",0,1],[112,"A",0,1],[144,"A",0,1],[176,"A",0,1],[208,"REST",0,1],[240,"REST",0,1],[256,"A",2,1],[288,"A",2,1],[320,"A",0,2]]
